import os
import torch
import pandas as pd
from tqdm import tqdm
from datasets import load_dataset
from transformers import AutoTokenizer, AutoModelForCausalLM, BitsAndBytesConfig

# 1. Identify all issue-spotting tasks in LegalBench
# The issue-spotting tasks are primarily prefixed with 'learnedhands' or 'issue_spotting' 
# (e.g., learnedhands_benefits, learnedhands_business, etc.)
ISSUE_SPOTTING_TASKS = [
    "learned_hands_benefits", "learned_hands_business", "learned_hands_consumer", 
    "learned_hands_crime", "learned_hands_divorce", "learned_hands_education", 
    "learned_hands_employment", "learned_hands_estate", "learned_hands_family", 
    "learned_hands_health", "learned_hands_housing", "learned_hands_immigration", 
    "learned_hands_insurance", "learned_hands_torts", "learned_hands_traffic"
]

# 2. Setup Quantized Model Configuration for Google Colab VRAM Safety
model_id = "google/gemma-2b-it" # Or use "google/gemma-2b" for base model

quantization_config = BitsAndBytesConfig(
    load_in_4bit=True,
    bnb_4bit_compute_dtype=torch.float16
)

print(f"Loading tokenizer and model: {model_id}...")
tokenizer = AutoTokenizer.from_pretrained(model_id)
model = AutoModelForCausalLM.from_pretrained(
    model_id,
    quantization_config=quantization_config,
    device_map="auto"
)

results_records = []

# 3. Loop through each issue spotting task
for task in ISSUE_SPOTTING_TASKS:
    print(f"\nEvaluating task: {task}...")
    try:
        # Load the test split for the specific task
        dataset = load_dataset("nguha/legalbench", task, split="test")
        
        # Limit to 50 samples per task as requested
        num_samples = min(50, len(dataset))
        sampled_dataset = dataset.select(range(num_samples))
        
        correct_predictions = 0
        
        for i, sample in enumerate(tqdm(sampled_dataset, desc=f"Processing {task}")):
            # Construct standard binary classification text prompt
            # LegalBench tasks typically use 'text' and 'answer' or 'label'
            text_input = sample['text']
            ground_truth = str(sample['answer']).strip().lower() # usually 'yes' or 'no'
            
            prompt = f"Analyze if the following text involves the relevant legal issue. Respond with only 'Yes' or 'No'.\n\nText: {text_input}\nAnswer:"
            
            # Generate model prediction
            inputs = tokenizer(prompt, return_tensors="pt").to("cuda")
            with torch.no_grad():
                outputs = model.generate(**inputs, max_new_tokens=3, temperature=0.0)
            
            # Extract just the newly generated text tokens
            generated_text = tokenizer.decode(outputs[0][inputs.input_ids.shape[-1]:], skip_special_tokens=True).strip().lower()
            
            # Determine success
            is_correct = ground_truth in generated_text
            if is_correct:
                correct_predictions += 1
            
            # Save raw performance rows for deep-dive analysis later
            results_records.append({
                "task": task,
                "sample_idx": i,
                "input_text": text_input,
                "ground_truth": ground_truth,
                "model_raw_output": generated_text,
                "is_correct": int(is_correct)
            })
            
        task_accuracy = correct_predictions / num_samples
        print(f"Task {task} Accuracy: {task_accuracy:.2%}")
        
    except Exception as e:
        print(f"Error evaluating task {task}: {e}")

# 4. Process and Save Outputs
df_results = pd.DataFrame(results_records)

# Mount Google Drive to save the output easily (Optional step)
# from google.colab import drive
# drive.mount('/content/drive')
